// === CONSTANTS & VALIDATION ===
const ROUNDING_DP = 2;
const REQUIRED_FIELDS = ['eventId', 'isin', 'eventType', 'mandatoryVoluntaryFlag', 'recordDate'];
const VALID_EVENT_TYPES = ['DVCA', 'DVSE', 'SPLF', 'RHTS', 'TEND', 'CHOS'];
const VALID_FLAGS = ['MAND', 'VOLU', 'CHOS'];

// Authentication is enforced natively by the Webhook Trigger node's Header Auth
// credential (n8n rejects any request with a missing or wrong X-Webhook-Secret
// with HTTP 401 before this node ever runs) - see docs/03a-security-architecture.md.
// This node no longer re-checks the secret: a prior version compared it here with
// a hardcoded literal and a bug that skipped validation when the header was absent
// (fixed 2026-08-16, see docs/log.md BK1-ISS-002).
const payload = $json.body || $json;

for (const field of REQUIRED_FIELDS) {
  if (!payload[field]) {
    throw new Error(`MISSING_FIELD: Mandatory field '${field}' is missing.`);
  }
}

if (!VALID_EVENT_TYPES.includes(payload.eventType)) {
  throw new Error(`INVALID_EVENT_TYPE: '${payload.eventType}' is not supported.`);
}

if (!VALID_FLAGS.includes(payload.mandatoryVoluntaryFlag)) {
  throw new Error(`INVALID_FLAG: '${payload.mandatoryVoluntaryFlag}' is not recognized.`);
}

if (['VOLU', 'CHOS'].includes(payload.mandatoryVoluntaryFlag) && !payload.electionDeadline) {
  throw new Error(`MISSING_ELECTION_DEADLINE: Voluntary event requires electionDeadline.`);
}

return {
  json: {
    ...payload,
    validatedAt: new Date().toISOString()
  }
};

function roundHalfUp(value, dp = 2) {
  const factor = Math.pow(10, dp);
  return Math.floor(value * factor + 0.5) / factor;
}

const pos = parseFloat($json.positionAsOfRecordDate || 0);
const rate = parseFloat($json.grossRatePerShare || 0);
const entitlementCash = roundHalfUp(pos * rate, 2);

return {
  json: {
    ...$json,
    entitlementCash,
    entitlementShares: null,
    fractionalCash: null,
    newPosition: null
  }
};

function roundHalfUp(value, dp = 2) {
  const factor = Math.pow(10, dp);
  return Math.floor(value * factor + 0.5) / factor;
}

const pos = parseFloat($json.positionAsOfRecordDate || 0);
const ratio = parseFloat($json.stockDividendRatio || 0);
const fracPrice = parseFloat($json.fractionalCashPrice || 0);

const rawShares = pos * ratio;
const entitlementShares = Math.floor(rawShares);
const fracRemainder = rawShares - entitlementShares;
const fractionalCash = roundHalfUp(fracRemainder * fracPrice, 2);

return {
  json: {
    ...$json,
    entitlementCash: 0.00,
    entitlementShares,
    fractionalCash,
    newPosition: null
  }
};

const pos = parseFloat($json.positionAsOfRecordDate || 0);
const ratioStr = $json.splitRatio || "1:1";
const parts = ratioStr.split(':').map(Number);
const newPos = pos * (parts[0] / parts[1]);

return {
  json: {
    ...$json,
    entitlementCash: 0.00,
    entitlementShares: 0,
    fractionalCash: 0.00,
    newPosition: newPos
  }
};

const pos = parseFloat($json.positionAsOfRecordDate || 0);
const ratio = parseFloat($json.rightsRatio || 0);
const rightsEntitlement = Math.floor(pos * ratio);

return {
  json: {
    ...$json,
    entitlementCash: 0.00,
    entitlementShares: rightsEntitlement,
    fractionalCash: 0.00,
    newPosition: null
  }
};

const pos = parseFloat($json.positionAsOfRecordDate || 0);

return {
  json: {
    ...$json,
    entitlementCash: 0.00,
    entitlementShares: pos,
    fractionalCash: 0.00,
    newPosition: null
  }
};

let escalationTier = 'NONE';
let daysToDeadline = null;

if (['VOLU', 'CHOS'].includes($json.mandatoryVoluntaryFlag) && $json.electionDeadline) {
  const deadline = new Date($json.electionDeadline);
  const now = new Date();
  const diffMs = deadline.getTime() - now.getTime();
  daysToDeadline = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (daysToDeadline > 10) {
    escalationTier = 'INFORMATIONAL';
  } else if (daysToDeadline >= 3 && daysToDeadline <= 10) {
    escalationTier = 'REMINDER';
  } else if (daysToDeadline >= 1 && daysToDeadline < 3) {
    escalationTier = 'URGENT';
  } else {
    escalationTier = 'BREACH'; // daysToDeadline <= 0 (FR-016)
  }
}

return {
  json: {
    ...$json,
    escalationTier,
    daysToDeadline
  }
};

// n8n's Google Sheets node in "lookup" mode REPLACES the item JSON with the
// matched row's columns - it does not merge with the incoming payload. Every
// node downstream of the lookup (starting with the Switch node's routing
// condition on eventType) needs fields from BOTH the original webhook payload
// and the looked-up position/rate data. Found by functional validation
// 2026-08-16 (see PORTFOLIO-HEALTH-REPORT.md) - without this node, the Switch
// node's $json.eventType would be undefined for every single request, and no
// event would ever route to a formula branch.
const validated = $('Validation Code Node').item.json;
const positionData = $json;

return {
  json: {
    ...validated,
    ...positionData
  }
};
